# DK HOA.  Hou - Odder - Aarhus H
#
let ha = path("d3.dk.hoa");

with detail = 3, railway = :first :pax :removed {
    with link = "point.dk.Hou", railway = :station {
        track(ha[:hou - 0.5sw, :hou + 0.5sw]);
        marker(:left :de.bf, ha[:hou] << 0.5mt);
        slabel(:right :bold, ha[:hou] >> 0.5mt + (1.4dt, 0.9dt), "Hou");
    }

    with link = "line.dk.HOA" {
        track(ha[:hou + 0.49sw, :hol - 0.49sw]);
    }

    with link = "point.dk.Holsatia", railway = :station {
        track(ha[:hol - 0.5sw, :hol + 0.5sw]);
        marker(:right :de.hp, ha[:hol] >> 0.5mt);
        slabel(:right, ha[:hol] >> 0.5mt >> 1sh + (1.2dt, 0.9dt),
            "Holsatia"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:hol + 0.49sw, :hol + 0.91km]);
        line_label(:right:sw, ha[:hol + 0.9km] >> 0.5mt, "HOA");
        track(ha[:hol + 0.89km, :hal - 0.49sw]);
    }

    with link = "point.dk.Halling", railway = :station {
        track(ha[:hal - 0.5sw, :hal + 0.5sw]);
        marker(:left :de.hp, ha[:hal] << 0.5mt);
        marker(:left :de.exbf, ha[:hal] << 0.5mt);
        slabel(:left, ha[:hal] << 0.5mt << 1.4sh + (-1.4dt, 1.3dt),
            "Halling"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:hal + 0.49sw, :bov - 0.49sw]);
    }

    with link = "point.dk.Bovlstrup", railway = :station {
        track(ha[:bov - 0.5sw, :bov + 0.5sw]);
        marker(:right :de.bf, ha[:bov] >> 0.5mt);
        slabel(:right, ha[:bov] >> 0.5mt >> 1sh + (1.4dt, 0.5dt),
            "Bovlstrup"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:bov + 0.49sw, :eri - 0.49sw]);
    }

    with link = "point.dk.Eriksminde", railway = :station {
        track(ha[:eri - 0.5sw, :eri + 0.5sw]);
        marker(:right :de.hp, ha[:eri] >> 0.5mt);
        slabel(:right, ha[:eri] >> 0.5mt >> 1sh + (1.4dt, 0.6dt),
            "Eriksminde"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:eri + 0.49sw, :nra - 0.49sw]);
    }

    with link = "point.dk.Neder-Randlev", railway = :station {
        track(ha[:nra - 0.5sw, :nra + 0.5sw]);
        marker(:right :de.hp, ha[:nra] >> 0.5mt);
        marker(:right :de.exbf, ha[:nra] >> 0.5mt);
        slabel(:right, ha[:nra] >> 0.5mt >> 1.4sh + (1.6dt, 0.2dt),
            "Neder Randlev"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:nra + 0.49sw, :nra + 1.41km]);
        line_label(:right:s, ha[:nra + 1.4km] >> 0.5mt, (0.3dt, 0dt), "HOA");
        track(ha[:nra + 1.39km, :odd.yh + 0.1dl]);
    }
}

with detail = 3, railway = :first :cat:dc75 :pax {
    with link = "point.dk.Odder", railway = :station {
        track(:removed, ha[:odd.yh, :odd - 0.49sw] << 1mt << 1ms);
        track(
                ha[:odd - 0.5sw, :odd + 0.5sw] << 1mt << 1ms
            --  ha[:odd + 0.5sw + 1dl, :odd + 0.5sw + 1.1dl]
        );
        track(ha[:odd.yh, :odd + 0.5sw + 2dl]);
        marker(:left :de.bf, ha[:odd] << 1ms << 1.5mt);
        slabel(:left :bold, ha[:odd] << 1ms << 1.5mt << 1sh + (-1.6dt, 1.0dt),
            "Odder"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:odd + 0.59sw - 0.9dl, :par - 0.49sw]);
    }

    with link = "point.dk.Parkvej", railway = :station {
        track(ha[:par - 0.5sw, :par + 0.5sw]);
        marker(:right :de.hp :removed, ha[:par] >> 0.5mt);
        slabel(:right :removed, ha[:par] >> 0.5mt >> 1sh + (1.3dt, 1.2dt),
            "Parkvej"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:par + 0.49sw, :rud - 0.49sw]);
    }

    with link = "point.dk.Rude-Havvej", railway = :station {
        track(ha[:rud - 0.5sw, :rud + 0.5sw]);
        marker(:left :de.hp, ha[:rud] << 0.5mt);
        slabel(:left, ha[:rud] << 0.5mt << 1sh + (-1.4dt, 0.9dt),
            "Rude Havvej"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:rud + 0.49sw, :rud + 1.31km]);
        line_label(:left:se, ha[:rud + 1.3km] << 0.5mt, "HOA");
        track(ha[:rud + 1.29km, :ass - 0.49sw]);
    }

    with link = "point.dk.Assedrup", railway = :station {
        track(ha[:ass - 0.5sw, :ass + 0.5sw]);
        marker(:right :de.bf, ha[:ass] >> 0.5mt);
        slabel(:right, ha[:ass] >> 0.5mt >> 1sh + (1.4dt, 1.8dt),
            "Assedrup"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:ass + 0.49sw, :ban - 0.49sw]);
    }

    with link = "point.dk.Banevolden", railway = :station {
        track(ha[:ban - 0.5sw, :ban + 0.5sw]);
        marker(:left :de.hp :removed, ha[:ban] << 0.5mt);
        slabel(:left :removed, ha[:ban] << 0.5mt << 1sh + (-1.4dt, 0.9dt),
            "Banevolden"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:ban + 0.49sw, :mal - 0.49sw]);
    }

    with link = "point.dk.Malling", railway = :station {
        track(ha[:mal - 0.5sw, :mal + 0.5sw]);
        marker(:right :de.bf, ha[:mal] >> 0.5mt);
        slabel(:right, ha[:mal] >> 0.5mt >> 1sh + (1.5dt, 0.9dt),
            "Malling"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:mal + 0.49sw, :ege - 0.49sw]);
    }

    with link = "point.dk.Egelund", railway = :station {
        track(ha[:ege - 0.5sw, :ege + 0.5sw]);
        marker(:right :de.hp :removed, ha[:ege] >> 0.5mt);
        slabel(:right :removed, ha[:ege] >> 0.5mt >> 1sh + (1.3dt, 1.2dt),
            "Egelund"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:ege + 0.49sw, :bed - 0.49sw]);
    }

    with link = "point.dk.Beder", railway = :station {
        track(ha[:bed - 0.5sw, :bed + 0.5sw]);
        marker(:right :de.hp, ha[:bed] >> 0.5mt);
        marker(:right :de.exbf, ha[:bed] >> 0.5mt);
        slabel(:right, ha[:bed] >> 0.5mt >> 1.4sh + (1.2dt, 1.1dt),
            "Beder"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:bed + 0.49sw, :vil - 0.49sw]);
    }

    with link = "point.dk.Vilhelmsborg", railway = :station {
        track(ha[:vil - 0.5sw, :vil + 0.5sw]);
        marker(:right :de.hp, ha[:vil] >> 0.5mt);
        slabel(:right, ha[:vil] >> 0.5mt >> 1sh + (1.5dt, 0.5dt),
            "Vilhelmsborg"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:vil + 0.49sw, :mar - 0.49sw]);
    }

    with link = "point.dk.Mårslet", railway = :station {
        track(ha[:mar - 0.5sw, :mar + 0.5sw]);
        marker(:left :de.bf, ha[:mar] << 0.5mt);
        slabel(:left, ha[:mar] << 0.5mt << 1sh + (-1.8dt, 1.8dt),
            "Mårslet"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:mar + 0.49sw, :mol - 0.49sw]);
    }

    with link = "point.dk.Mølleparken", railway = :station {
        track(ha[:mol - 0.5sw, :mol + 0.5sw]);
        marker(:left :de.hp, ha[:mol] << 0.5mt);
        slabel(:left, ha[:mol] << 0.5mt << 1sh + (-1.4dt, 1.2dt),
            "Mølleparken"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:mol + 0.49sw, :gun - 0.49sw]);
    }

    with link = "point.dk.Gunnestrup", railway = :station {
        track(ha[:gun - 0.5sw, :gun + 0.5sw]);
        marker(:right :de.hp :removed, ha[:gun] >> 0.5mt);
        marker(:right :de.exbf :removed, ha[:gun] >> 0.5mt);
        slabel(:right :removed, ha[:gun] >> 0.5mt >> 1.4sh + (1.3dt, 0.9dt),
            "Gunnestrup"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:gun + 0.49sw, :nor - 0.49sw]);
    }

    with link = "point.dk.Nørrevænget", railway = :station {
        track(ha[:nor - 0.5sw, :nor + 0.5sw]);
        marker(:left :de.hp, ha[:nor] << 0.5mt);
        slabel(:left, ha[:nor] << 0.5mt << 1sh + (-1dt, 2.3dt),
            "Nørrevænget"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:nor + 0.49sw, :hav - 0.49sw]);
    }

    with link = "point.dk.Havebyen", railway = :station {
        track(ha[:hav - 0.5sw, :hav + 0.5sw]);
        marker(:left :de.hp :removed, ha[:hav] << 0.5mt);
        slabel(:right :removed, ha[:hav] >> 0.5mt + (1dt, -0.3dt),
            "Havebyen"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:hav + 0.49sw, :tra - 0.49sw]);
    }

    with link = "point.dk.Tranbjerg", railway = :station {
        track(ha[:tra - 0.5sw, :tra + 0.5sw]);
        marker(:left :de.bf, ha[:tra] << 0.5mt);
        slabel(:left, ha[:tra] << 0.5mt << 1sh + (-1.5dt, 1.3dt),
            "Tranbjerg"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:tra + 0.49sw, :tra + 0.61km]);
        line_label(:right:w, ha[:tra + 0.6km] >> 0.5mt, (0dt, -0.1dt), "HOA");
        track(
                ha[:tra + 0.59km, :vib.zo - 0.5mt]
            ..  ha[:gcl - 0.5sw, :gcl - 0.49sw] >> 0.5mt
        );
    }

    with link = "point.dk.Gunnar-Clausensvej", railway = :station {
        track(ha[:gcl - 0.5sw, :gcl + 0.5sw] >> 0.5mt);
        marker(:left :de.hp, ha[:gcl]);
        slabel(:right, ha[:gcl] >> 0.5mt + (1.0dt, 2.6dt),
            "Gunnar Clausensvej"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:gcl + 0.49sw, :oll - 0.49sw] >> 0.5mt);
    }

    with link = "point.dk.Øllegårdsvej", railway = :station {
        track(ha[:oll - 0.5sw, :oll + 0.5sw] >> 0.5mt);
        marker(:left :de.hp :casing, ha[:oll]);
        slabel(:top, ha[:oll] + (0dt, -0.35km) + (-2dt, -1.5dt),
            "Øllegårdsvej"
        );
    }

    with link = "line.dk.HOA" {
        track(
                ha[:oll + 0.49sw, :oll + 0.5sw] >> 0.5mt
            ..  ha[:ros - 0.5sw, :ros - 0.49sw] >> 0.5md >> 1ms >> 0.5mt
        );
    }

    with link = "point.dk.Rosenhøj", railway = :station {
        track(ha[:ros - 0.5sw, :ros + 0.5sw] >> 0.5md >> 1ms >> 0.5mt);
        marker(:right :de.hp,
                ha[:ros] >> 0.5md >> 1ms >> 1mt,
                ha[:ros] >> 0.5md >> 1ms
        );
        slabel(:right,
            ha[:ros] >> 0.5md >> 1ms >> 0.5mt >> 1sh + (1.8dt, 0.6dt),
            "Rosenhøj"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:ros + 0.49sw, :vib - 0.49sw] >> 0.5md >> 1ms >> 0.5mt);
    }

    # point.dk.Viby-Jylland  dk.FFH

    with link = "line.dk.HOA" {
        track(:lor, ha[:vib + 0.5sw, :kon - 0.5sw] >> 0.5md >> 1ms >> 0.5mt);
    }

    with link = "point.dk.Kongsvang", railway = :station {
        track(ha[:kon - 0.5sw, :kon + 0.5sw] >> 0.5md >> 1ms >> 0.5mt);
        marker(:right :de.hp,
                ha[:kon] >> 0.5md >> 1ms >> 1mt,
                ha[:kon] >> 0.5md >> 1ms
        );
        slabel(:right,
            ha[:kon] >> 0.5md >> 1ms >> 0.5mt >> 1sh + (1.3dt, 1dt),
            "Kongsvang"
        );
    }

    with link = "line.dk.HOA" {
        track(:station, ha[:kon + 0.49sw, :aar.yt] >> 0.5md >> 1ms >> 0.5mt);
        with layer = -1 track(:station,
                ha[:aar.yt - 0.1dl, :aar.yt] >> 0.5md >> 1ms >> 0.5mt
            ..  ha[:aar.yr, :aar.yr + 0.1dl] << 0.5md << 1ms << 0.5mt
        );
        track(:lor:ror, ha[:aar.yr, :aar - 0.99km] << 0.5md << 1ms << 0.5mt);
    }
}

